<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/paystack.php';$db=db();$reference=preg_replace('/[^A-Za-z0-9._-]/','',(string)($_GET['reference']??''));if($reference===''){http_response_code(400);exit('Missing payment reference.');}$r=paystack_request('GET','transaction/verify/'.rawurlencode($reference));if(!$r['ok']){http_response_code(400);exit('Payment verification failed.');}$d=$r['data']['data']??[];$status=($d['status']??'')==='success'?'successful':'failed';$q=$db->prepare('SELECT * FROM invoice_payments WHERE reference=? LIMIT 1');$q->execute([$reference]);$payment=$q->fetch();if(!$payment){http_response_code(404);exit('Payment record not found.');}if($payment['status']==='successful'){header('Location: invoice-view.php?token='.urlencode((string)json_decode((string)$payment['metadata'],true)['invoice_token']??''));exit;}$db->beginTransaction();try{$db->prepare('UPDATE invoice_payments SET status=?,gateway_transaction_id=?,paid_at=CASE WHEN ?="successful" THEN NOW() ELSE NULL END,metadata=? WHERE id=?')->execute([$status,(string)($d['id']??''),$status,json_encode($d),$payment['id']]);if($status==='successful'){$sum=$db->prepare("SELECT COALESCE(SUM(amount),0) FROM invoice_payments WHERE invoice_id=? AND status='successful'");$sum->execute([$payment['invoice_id']]);$paid=(float)$sum->fetchColumn();$inv=$db->prepare('SELECT total FROM invoices WHERE id=?');$inv->execute([$payment['invoice_id']]);$total=(float)$inv->fetchColumn();$balance=max(0,$total-$paid);$newStatus=$balance<=0?'paid':'partially_paid';$db->prepare('UPDATE invoices SET amount_paid=?,balance_due=?,status=? WHERE id=?')->execute([$paid,$balance,$newStatus,$payment['invoice_id']]);$db->prepare('INSERT INTO invoice_events (invoice_id,event_type,description) VALUES (?,?,?)')->execute([$payment['invoice_id'],'payment_success','Paystack payment '.$reference.' verified successfully.']);$db->prepare('INSERT INTO lead_activities (lead_id,activity_type,subject,description) VALUES (?,?,?,?)')->execute([$payment['lead_id'],'payment','Payment received','Paystack payment '.$reference.' received for invoice.']);}$db->commit();$meta=json_decode((string)$payment['metadata'],true);$token=(string)($meta['invoice_token']??'');header('Location: invoice-view.php?token='.urlencode($token).'&payment='.urlencode($status));exit;}catch(Throwable $e){$db->rollBack();http_response_code(500);exit('Unable to record payment.');}
